#!/usr/bin/env node
/**
 * gen-validators.mjs — Phase-10 Task 10.3.29 item 1.
 *
 * Reads the checked-in OpenAPI 3.1 artifact (`docs/openapi/openapi.json` —
 * the DERIVED route-registry document, regenerated by
 * `services/cmd/openapi-gen`, never hand-edited) and emits a typed route
 * contract table for the input-helper framework:
 *
 *   src/lib/input-helpers/generated/route-contracts.ts
 *
 * The emitted `ROUTE_CONTRACTS` map is keyed `"<METHOD> <path>"` and
 * carries every declared constraint the document encodes: auth/scopes,
 * role, rate tier, route status (live|stub), dual-control flag, path
 * params and any parameter-level schema (type/enum/pattern/min/max).
 *
 * KNOWN LIMITATION (honest): the published document is a route-registry
 * dump — it declares no requestBody schemas, so body-field rules cannot
 * be generated. Body-level structural validation lives in
 * `field-rules.ts` (mirroring `services/internal/orders/validate.go`
 * etc. with provenance comments). When the document gains body schemas,
 * this generator emits them into `requestFields` and the hand-kept
 * registry shrinks to zero.
 *
 * Usage: node scripts/gen-validators.mjs [--check]
 *   --check  verify the generated file is current (CI drift gate)
 */
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(HERE, '..');
const SPEC = resolve(ROOT, '../docs/openapi/openapi.json');
const OUT = resolve(ROOT, 'src/lib/input-helpers/generated/route-contracts.ts');

const checkOnly = process.argv.includes('--check');

const doc = JSON.parse(readFileSync(SPEC, 'utf8'));
const paths = doc.paths ?? {};

const HEADER = `// @generated by scripts/gen-validators.mjs — DO NOT EDIT.
// Source: docs/openapi/openapi.json (derived from services/internal/
// gateway/routes_v1.go via services/cmd/openapi-gen).
// Regenerate: npm run gen:validators

export interface RouteParamSchema {
  readonly name: string;
  readonly in: 'path' | 'query';
  readonly required: boolean;
  readonly type: string;
  readonly enum: readonly string[] | null;
  readonly pattern: string | null;
  readonly minimum: number | null;
  readonly maximum: number | null;
}

export interface RouteContract {
  readonly method: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';
  readonly path: string;
  /** Registry status: 'live' = handler mounted; 'stub' = 501
   * NOT_IMPLEMENTED until the owning phase lands the handler. Treat as a
   * hint — runtime 501 detection (availability.ts) is authoritative. */
  readonly status: 'live' | 'stub';
  readonly authRequired: boolean;
  readonly scopes: readonly string[];
  readonly role: string | null;
  readonly methods: readonly string[] | null;
  readonly rateTier: string;
  readonly weight: number;
  readonly dualControl: boolean;
  readonly owner: string;
  readonly summary: string;
  readonly params: readonly RouteParamSchema[];
  /** Env binding when the route is environment-gated (x-env). */
  readonly env: string | null;
}
`;

const METHODS = new Set(['get', 'post', 'put', 'patch', 'delete']);

function emitString(s) {
  return JSON.stringify(s);
}

function emitParam(p) {
  const schema = p.schema ?? {};
  const parts = [
    `name: ${emitString(p.name)}`,
    `in: ${emitString(p.in === 'query' ? 'query' : 'path')}`,
    `required: ${p.required === true}`,
    `type: ${emitString(typeof schema.type === 'string' ? schema.type : 'string')}`,
  ];
  parts.push(`enum: ${Array.isArray(schema.enum) ? emitString(schema.enum.map(String)) : 'null'}`);
  parts.push(
    `pattern: ${typeof schema.pattern === 'string' ? emitString(schema.pattern) : 'null'}`,
  );
  parts.push(`minimum: ${typeof schema.minimum === 'number' ? schema.minimum : 'null'}`);
  parts.push(`maximum: ${typeof schema.maximum === 'number' ? schema.maximum : 'null'}`);
  return `{ ${parts.join(', ')} }`;
}

const entries = [];
for (const [path, item] of Object.entries(paths)) {
  if (!item || typeof item !== 'object') continue;
  for (const [m, op] of Object.entries(item)) {
    if (!METHODS.has(m) || !op || typeof op !== 'object') continue;
    const method = m.toUpperCase();
    const xa = op['x-auth'] ?? {};
    const params = Array.isArray(op.parameters) ? op.parameters : [];
    const contract = [
      `method: ${emitString(method)}`,
      `path: ${emitString(path)}`,
      `status: ${op['x-status'] === 'live' ? "'live'" : "'stub'"}`,
      `authRequired: ${xa.required === true}`,
      `scopes: ${Array.isArray(xa.scopes) ? emitString(xa.scopes) : '[]'}`,
      `role: ${typeof xa.role === 'string' && xa.role !== '' ? emitString(xa.role) : 'null'}`,
      `methods: ${Array.isArray(xa.methods) ? emitString(xa.methods) : 'null'}`,
      `rateTier: ${emitString(typeof op['x-rate-tier'] === 'string' ? op['x-rate-tier'] : 'basic')}`,
      `weight: ${typeof op['x-weight'] === 'number' ? op['x-weight'] : 1}`,
      `dualControl: ${op['x-dual-control'] === true}`,
      `owner: ${emitString(typeof op['x-owner'] === 'string' ? op['x-owner'] : '')}`,
      `summary: ${emitString(typeof op.summary === 'string' ? op.summary : '')}`,
      `params: [${params.map(emitParam).join(', ')}]`,
      `env: ${typeof op['x-env'] === 'string' && op['x-env'] !== '' ? emitString(op['x-env']) : 'null'}`,
    ];
    entries.push(`  ${emitString(`${method} ${path}`)}: {\n    ${contract.join(',\n    ')},\n  },`);
  }
}

// Format with the project's prettier config so `npm run format:check`
// stays green on a generated artifact (prettier is a devDep — import it
// lazily so a bare `node` without node_modules still gets a usable file).
let body = `${HEADER}
export const ROUTE_CONTRACTS: Readonly<Record<string, RouteContract>> = {
${entries.join('\n')}
};

export const ROUTE_KEYS = Object.keys(ROUTE_CONTRACTS) as readonly string[];

/** Resolve a contract by "METHOD /path" (also tolerates lowercase method). */
export function routeContract(key: string): RouteContract | undefined {
  const sp = key.indexOf(' ');
  if (sp <= 0) return undefined;
  return ROUTE_CONTRACTS[\`\${key.slice(0, sp).toUpperCase()}\${key.slice(sp)}\`];
}
`;
try {
  const prettier = await import('prettier');
  const config = (await prettier.resolveConfig(OUT)) ?? { parser: 'typescript' };
  body = await prettier.format(body, { ...config, parser: 'typescript' });
} catch (err) {
  console.warn(`gen-validators: prettier unavailable (${err.message}) — emitting raw output`);
}

const existing = (() => {
  try {
    return readFileSync(OUT, 'utf8');
  } catch {
    return null;
  }
})();

if (checkOnly) {
  if (existing !== body) {
    console.error(
      'gen-validators: route-contracts.ts is stale — regenerate with `npm run gen:validators`',
    );
    process.exit(1);
  }
  console.log(`gen-validators: current (${entries.length} operations)`);
  process.exit(0);
}

if (existing === body) {
  console.log(`gen-validators: unchanged (${entries.length} operations)`);
} else {
  mkdirSync(dirname(OUT), { recursive: true });
  writeFileSync(OUT, body);
  console.log(`gen-validators: wrote ${OUT} (${entries.length} operations)`);
}
